-- Lote 10: traduções PT-BR de talentos SRD (6 registros).
update public.srd_feats as f
set nome_pt = v.nome_pt,
    descricao_pt = v.descricao_pt
from (values
('srd35_feat_forge_ring','Forjar Anel','Pré-requisito: Nível de conjurador 12º.\n\nBenefício: Você pode criar qualquer anel cujos pré-requisitos consiga cumprir. A fabricação de um anel exige um dia para cada 1.000 PO de seu preço-base. Para fabricar um anel, você deve gastar XP equivalente a 1/25 de seu preço-base e consumir matérias-primas que custem metade desse preço.\n\nVocê também pode consertar um anel quebrado, desde que seja capaz de fabricar esse anel. O conserto custa metade do XP, metade das matérias-primas e metade do tempo necessários para fabricar o anel originalmente.\n\nAlguns anéis mágicos exigem custos adicionais em componentes materiais ou XP, conforme indicado em suas descrições. Você deve pagar esses custos para fabricar ou consertar esses anéis.'),
('srd35_feat_great_cleave','Trespassar Maior','Pré-requisitos: Força 13, Trespassar, Ataque Poderoso, Bônus Base de Ataque +4.\n\nBenefício: Este talento funciona como Trespassar, mas não há limite para o número de vezes que você pode utilizá-lo por rodada.\n\nEspecial: Um guerreiro pode escolher Trespassar Maior como um de seus talentos adicionais de guerreiro.'),
('srd35_feat_great_fortitude','Fortitude Maior','Benefício: Você recebe +2 de bônus em todos os seus testes de resistência de Fortitude.'),
('srd35_feat_greater_spell_focus','Foco em Magia Maior','Escolha uma escola de magia à qual você já tenha aplicado o talento Foco em Magia.\n\nBenefício: A CD de todos os testes de resistência contra magias da escola escolhida aumenta em +1. Este bônus se acumula com o bônus de Foco em Magia.\n\nEspecial: Você pode escolher este talento várias vezes. Seus efeitos não se acumulam entre si. Cada vez que escolher o talento, ele se aplica a uma escola diferente à qual você já tenha aplicado Foco em Magia.'),
('srd35_feat_greater_spell_penetration','Penetração de Magia Maior','Pré-requisito: Penetração de Magia.\n\nBenefício: Você recebe +2 de bônus nos testes de nível de conjurador (1d20 + nível de conjurador) realizados para superar a resistência à magia de uma criatura. Este bônus se acumula com o concedido por Penetração de Magia.'),
('srd35_feat_greater_two_weapon_fighting','Combater com Duas Armas Aprimorado Maior','Pré-requisitos: Destreza 19, Combater com Duas Armas Aprimorado, Combater com Duas Armas, Bônus Base de Ataque +11.\n\nBenefício: Você recebe um terceiro ataque com sua arma secundária, com penalidade de –10.\n\nEspecial: Um guerreiro pode escolher este talento como um de seus talentos adicionais de guerreiro.\n\nUm ranger de 11º nível que tenha escolhido o estilo de combate com duas armas é considerado como possuidor deste talento, mesmo que não cumpra seus pré-requisitos, mas somente quando estiver usando armadura leve ou nenhuma armadura.')
) as v(id,nome_pt,descricao_pt)
where f.id = v.id;
